<div class="page-head"><div><p class="eyebrow">Administration</p><h1>Product Management</h1><p>Add, edit and remove products from the inventory.</p></div><?php if($edit):?><a class="btn light" href="products.php">＋ New Product</a><?php endif;?></div>
<section class="panel"><div class="panel-head"><div><h2><?=$edit?'Edit Product':'Add New Product'?></h2><span class="panel-sub">Only Admin can manage product master data.</span></div></div><form method="post" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Product Name</label><input name="name" value="<?=e($edit['name']??'')?>" required maxlength="150"></div><div class="field"><label>SKU</label><input name="sku" value="<?=e($edit['sku']??'')?>" required maxlength="80" pattern="[A-Za-z0-9_-]{2,80}"><span class="helper">SKU must be unique.</span></div><div class="field"><label>Category</label><select name="category_id"><option value="0">— Select category —</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=isset($edit['category_id'])&&$edit['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Price (৳)</label><input type="number" step="0.01" min="0" name="price" value="<?=e($edit['price']??'0')?>" required></div><div class="field"><label>Stock Quantity</label><input type="number" min="0" name="quantity" value="<?=e($edit['quantity']??'0')?>" required></div><div class="field"><label>Reorder Level</label><input type="number" min="0" name="reorder_level" value="<?=e($edit['reorder_level']??'5')?>" required></div></div><div class="form-actions"><button class="btn"><?=$edit?'✓ Update Product':'＋ Add Product'?></button><?php if($edit):?><a class="btn gray" href="products.php">Cancel</a><?php endif;?></div></form></section><br>
<section class="panel"><div class="panel-head"><div><h2>All Products</h2><span class="panel-sub"><?=count($ps)?> products in the system</span></div><div class="search-row"><input id="productSearch" type="search" placeholder="Search product or SKU..." aria-label="Search product or SKU"></div></div><div id="ajaxResults" class="ajax-results" aria-live="polite"></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr><?php foreach($ps as $p):?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['sku'])?></td><td><?=e($p['category']??'Uncategorized')?></td><td>৳<?=number_format((float)$p['price'],2)?></td><td><?=e($p['quantity'])?></td><td><?=$p['quantity']==0?'<span class="badge red">Out of stock</span>':($p['quantity']<=$p['reorder_level']?'<span class="badge red">Low stock</span>':'<span class="badge green">Healthy</span>')?></td><td class="actions"><a class="btn small" href="products.php?edit=<?=$p['id']?>">✎ Edit</a><form method="post" class="inline-form" onsubmit="return confirmDelete('Delete this product?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="delete_id" value="<?=$p['id']?>"><button class="btn small danger" type="submit">Delete</button></form></td></tr><?php endforeach;?><?php if(!$ps):?><tr><td colspan="7" class="empty">No products found.</td></tr><?php endif;?></table></div></section>
